  "body": " Story   Finish the input statements below to ask the user for 2 colors and a food item. Run to see the silly poem. Then, ask the user for more input words and create your own poem or story using the variables in print statements.    # Get user input pluralnoun1 = input(\"Enter a plural noun: \") pluralnoun2 = input(\"Enter another plural noun: \") # Complete 3 input statements below color1 = input( ) color2 = food = # create 2 more variables and input statements # Run to see the silly poem print(\"Here's my silly poem!\") print(\"Roses are \" + color1) print(pluralnoun1 + \" are \" + color2) print(\"I like \" + food) print(\"Do \" + pluralnoun2 + \" like them too?\") # Add at least 2 more lines to the poem # using print and your last 2 variables  from unittest.gui import TestCaseGui class myTests(TestCaseGui): def test1(self): self.assertIn(\"I like\",self.getOutput(),\"output\") input_count = self.getEditorText().count(\"input(\") self.assertLessEqual(7,input_count, \"at least 7 input statements\") myTests().main()   "
